<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigMagicLinkEnabledAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigMagicLinkEnabledAccessor trait.
 *
 * Covers null default, string/VO assignment via withMagicLinkEnabled,
 * getMagicLinkEnabled/magicLinkEnabled accessors, and isMagicLinkEnabledChanged with/without original.
 */
class TenantConfigMagicLinkEnabledAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withMagicLinkEnabled creates a new instance with the MagicLinkEnabled set
     * from a string value, and getMagicLinkEnabled returns the primitive string.
     */
    public function testWithMagicLinkEnabledFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigMagicLinkEnabledAccessorUnitTest();

        // Act
        $result = $holder->withMagicLinkEnabled(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isMagicLinkEnabled());
    }
    /**
     * Asserts that withmagicLinkEnabled has access to the value object
     * from a string value, and getMagicLinkEnabled returns the primitive string.
     */
    public function testWithMagicLinkEnabledFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigMagicLinkEnabledAccessorUnitTest();

        // Act
        $result = $holder->withMagicLinkEnabled(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->magicLinkEnabled()->value());
    }
    public function testChangedMagicLinkEnabled(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigMagicLinkEnabledAccessorUnitTest();
        $original = $holder->withMagicLinkEnabled(true);
        $same = $holder->withMagicLinkEnabled(true);
        $modified = $holder->withMagicLinkEnabled(false);

        // Act
        $unchanged = $holder->isMagicLinkEnabledChanged();
        $withSame = $original->isMagicLinkEnabledChanged($same);
        $withDiferent = $original->isMagicLinkEnabledChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigMagicLinkEnabledAccessorUnitTest
{
    use TenantConfigMagicLinkEnabledAccessor;
}
